args.command:
python3 << 'EOF'
try:
    from PyPDF2 import PdfReader
    reader = PdfReader("/work/report.pdf")
    print(f"Number of pages: {len(reader.pages)}")
except ImportError:
    try:
        import pypdf
        reader = pypdf.PdfReader("/work/report.pdf")
        print(f"Number of pages: {len(reader.pages)}")
    except ImportError:
        print("PDF libraries not available")
EOF
